async function pool(items, limit, fn) {
  const results = []; let i = 0;
  const workers = Array.from({ length: limit }, async () => { while (i < items.length) { const idx = i++; results[idx] = await fn(items[idx]); } });
  await Promise.all(workers);
  return results;
}
