async function retry(fn, { retries = 3, delay = 200 } = {}) {
  for (let attempt = 0; ; attempt++) {
    try { return await fn(); }
    catch (err) {
      if (attempt >= retries) throw err;
      await wait(delay * 2 ** attempt);        // 200, 400, 800 ms...
    }
  }
}
